#pragma once

#include <optional>
#include <span>

#include <cube/solver/cube.hpp>

#include "cubie.hpp"

// The intermediate solver's last layer, as two table lookups. The tables are
// generated by tools/cfop_tables and checked in as cfop_case_words.inc; there
// is no search here, and every entry is the shortest sequence over <U, R, F>
// for its case. The compiler turns the .inc's text into move arrays (a
// malformed entry is a compile error), so a lookup is an index and a span.
//
// Both functions expect the first two layers already solved, and read only
// the four U-layer corners and edges (see cfop_case_index.hpp).

namespace cube::solver::detail {

// The moves that orient the whole last layer - every U-layer corner turned
// to show the top colour, every U-layer edge flipped to - or nullopt if the
// table has no usable entry (which a valid cube never reaches). The span
// refers to static storage and stays valid for the life of the program.
[[nodiscard]] std::optional<std::span<const Move>> oll_algorithm(const CubieCube& cube) noexcept;

// The moves that put an already-oriented last layer's pieces where they
// belong, finishing the cube, or nullopt if `cube`'s last layer is not
// oriented or its corner and edge parities disagree (a real cube's never do).
[[nodiscard]] std::optional<std::span<const Move>> pll_algorithm(const CubieCube& cube) noexcept;

}  // namespace cube::solver::detail
